def pin_launch(request: Request, requested: str | None) -> AutomaticLaunch:
    current = configured_scope(request)
    if requested is not None:
        supplied = AutomaticScope.model_validate_json(requested)
        if supplied != current:
            raise HTTPException(409, detail="Состав цикла изменился. Обновите настройки запуска.")
    return AutomaticLaunch(scope=current, cycle_id=str(uuid4()))

