skillRegistry.excerpt:
def activate(self, skill_ids: Sequence[str]) -> tuple[ActivatedSkill, ...]:
    ordered: list[_RegisteredSkill] = []
    resolved: set[str] = set()
    resolving: list[str] = []

    def resolve(skill_id: str) -> None:
        if skill_id in resolved:
            return
        if skill_id in resolving:
            cycle = " -> ".join([*resolving, skill_id])
            raise SkillValidationError(f"cyclic skill dependency: {cycle}")
        try:
            registered = self._skills[skill_id]
        except KeyError as error:
            raise SkillValidationError(
                f"skill dependency is not registered: {skill_id}"
            ) from error
        resolving.append(skill_id)
        for dependency in registered.package.dependencies:
            resolve(dependency.skill_id)
            actual = self._skills[dependency.skill_id].package
            if dependency.version is not None and dependency.version != actual.version:
                raise SkillValidationError(
                    f"skill {skill_id} requires {dependency.skill_id} version "
                    f"{dependency.version}, got {actual.version}"
                )
            if (
                dependency.content_hash is not None
                and dependency.content_hash != actual.content_hash
            ):
                raise SkillValidationError(
                    f"skill {skill_id} requires a different {dependency.skill_id} content hash"
                )
        resolving.pop()
        resolved.add(skill_id)
        ordered.append(registered)

    for skill_id in skill_ids:
        resolve(skill_id)
    return tuple(
        ActivatedSkill(
            package=registered.package,
            instructions=self.loader.load_instructions(registered.root),
        )
        for registered in ordered

