def role_instruction(role: str) -> tuple[str, str]:
    if role not in ROLES:
        raise DraftError("unsupported_role", "No registered model instruction for this role")
    filename, expected = ROLES[role]
    content = (INSTRUCTIONS / filename).read_bytes()
    digest = hashlib.sha256(content).hexdigest()
    if digest != expected:
        raise DraftError(
            "instruction_changed", "Instruction revision requires explicit registration", 409
        )
    return content.decode("utf-8"), digest

geometryMentions.excerpt:
"""Conservative occurrence matching in an agent description, not drawing recognition."""

import hashlib
import re

from .models import DescriptionLocation, EvidenceRef, Feature, GeometryMention, RecognitionStatus


def description_mentions(
    description: str,
    evidence: EvidenceRef,
    bindings: list[tuple[str, Feature]] | None = None,
    locations: list[DescriptionLocation] | None = None,
) -> list[GeometryMention]:
    result = []
    pattern = r"[Ø⌀]\s*\d+(?:[.,]\d+)?"
    occurrences = {
        (match.start(), match.group()): match.end() for match in re.finditer(pattern, description)
    }
    addresses: dict[tuple[int, str], list[DescriptionLocation]] = {}
    for location in locations or []:
        if description.count(location.quote) != 1:
            continue
        offset = description.find(location.quote)
        matches = list(
            re.finditer(
                re.escape(location.target_text) if location.target_text else pattern, location.quote
            )
        )
        if location.occurrence >= len(matches):
            continue
        match = matches[location.occurrence]
        key = (offset + match.start(), match.group())
        occurrences[key] = offset + match.end()
        addresses.setdefault(key, []).append(location)
    for (offset, target_text), target_end in sorted(occurrences.items()):
        start = description.rfind("\n", 0, offset) + 1
        end = description.find("\n", target_end)
        if end < 0:
            end = len(description)
        # One warning per occurrence; same number or same line is not an identity.
        quote = description[start:end]
        legacy_target = re.fullmatch(pattern, target_text) is not None
        identity = f"{description}\0{offset}" + ("" if legacy_target else f"\0{target_text}")
        identifier = hashlib.sha256(identity.encode()).hexdigest()[:20]
        targets = []
        for bound_quote, feature in bindings or []:
            if len(bound_quote.strip()) < 12 or description.count(bound_quote) != 1:
                continue
            bound_offset = description.find(bound_quote)
            if bound_offset <= target_end - len(target_text) and target_end <= bound_offset + len(
                bound_quote
            ):
                targets.append(feature)
        feature = targets[0] if len(targets) == 1 else None
        addressed = addresses.get((target_end - len(target_text), target_text), [])
        location = addressed[0] if len(addressed) == 1 else None
        role = feature.geometry_role if feature else "unresolved"
        if role == "unknown":
            role = "unresolved"
        result.append(
            GeometryMention(
                id=f"mention-{identifier}",
                quote=quote,
                target_text=target_text,
                location_status=location.status if location else "not_found",
                location_note=location.note
                if location
                else "Точная адресная область не передана или цитата неоднозначна.",
                location_evidence=location.evidence_refs if location else (),
                start=start,
                end=end,
                role=role,
                feature_ref=feature.id if feature and role == "surface" else None,
                reason="Агент связал точную цитату описания с элементом; требуется сверка оригинала."
                if role != "unresolved"
                else None,
                evidence=evidence.model_copy(
                    update={
                        "raw_text": quote,
                        "recognition_status": RecognitionStatus.UNCERTAIN,
                        "normalized_bbox": None,
                        "annotation_refs": (),
                    }
                ),
            )
        )
    return result

