"""Exact reference spelling shared by typed perception and inventory projections."""

from __future__ import annotations

from typing import Any

_COLLECTIONS = (
    "dimensions",
    "features",
    "geometry_relations",
    "general_tolerances",
    "standard_references",
    "stock_prescriptions",
    "technical_requirements",
    "local_reference_definitions",
    "local_reference_uses",
    "unmapped_facts",
)

# Only annotation mappings can address view context and local notation.
# A view is not a geometric owner or a grounded passport fact.
ANNOTATION_TARGET_NAMESPACES = (
    "header",
    *_COLLECTIONS,
    "roughness.general",
    "roughness.local",
    "quality_control_ids",
    "views",
)


def annotation_reference_sets(passport: Any) -> tuple[set[str], set[str]]:
    facts = {
        "part_name",
        "drawing_designation",
        "part_class",
        "material",
        "scale",
        "drawing_mass",
        "drawing_quantity",
    }
    for collection in _COLLECTIONS:
        facts.update(item.id for item in getattr(passport, collection))
    facts.update(f"quality_control:{i}" for i, _ in enumerate(passport.quality_control_ids))
    if passport.roughness.general is not None:
        facts.add("roughness.general")
    facts.update(f"roughness.local:{i}" for i, _ in enumerate(passport.roughness.local))
    return facts, {view.id for view in passport.views}


def resolve_existing_fact_reference(
    candidate: dict[str, Any], ref: str, *, field_path: bool = False
) -> str:
    """Resolve qualified IDs only against an existing fact in that exact collection.

    Literal IDs (including dots) take precedence. Unknown targets and incorrect collection
    names remain unchanged. A conflict field path may refer to an existing record attribute,
    with either a bare record ID or its collection-qualified spelling.
    """
    ids_by_collection = {
        field: {item["id"] for item in candidate.get(field, [])} for field in _COLLECTIONS
    }
    if ref in set().union(*ids_by_collection.values()):
        return ref
    if field_path:
        identifier, separator, attribute = ref.rpartition(".")
        if separator:
            for field, identifiers in ids_by_collection.items():
                if identifier in identifiers:
                    item = next(item for item in candidate[field] if item["id"] == identifier)
                    if attribute in item:
                        return identifier
    collection, _, identifier = ref.partition(".")
    if collection not in ids_by_collection:
        return ref
    if identifier in ids_by_collection[collection]:
        return identifier
    if field_path:
        identifier, _, attribute = identifier.rpartition(".")
        for item in candidate.get(collection, []):
            if item["id"] == identifier and attribute in item:
                return identifier
    return ref


def normalize_existing_fact_references(candidate: dict[str, Any]) -> None:
    """Normalize reference spelling without changing facts or their source evidence."""
    ref_fields = []
    for conflict in candidate.get("source_conflicts", []):
        conflict["field_ref"] = resolve_existing_fact_reference(
            candidate, conflict["field_ref"], field_path=True
        )
        ref_fields.append((conflict, "affected_refs"))
        ref_fields.extend((alternative, "fact_refs") for alternative in conflict["alternatives"])
    for record, field in ref_fields:
        record[field] = [
            resolve_existing_fact_reference(candidate, ref) for ref in record.get(field, [])

