class GeometryMention(ContractModel):
    """An occurrence in a model description, never a newly read drawing fact."""

    id: str
    quote: str = Field(min_length=1)
    start: int = Field(ge=0)
    end: int = Field(gt=0)
    role: Literal["unresolved", "surface", "stock", "position", "other"] = "unresolved"
    feature_ref: str | None = None
    target_description: str | None = Field(default=None, exclude_if=lambda value: value is None)
    view_description: str | None = Field(default=None, exclude_if=lambda value: value is None)
    reason: str | None = None
    evidence: EvidenceRef
    target_text: str | None = None
    location_status: Literal["located", "candidate", "not_found"] = "not_found"
    location_note: str | None = None
    location_evidence: tuple[EvidenceRef, ...] = ()

    @model_validator(mode="after")
    def validate_resolution(self) -> GeometryMention:
        if self.location_status == "not_found" and self.location_evidence:
            raise ValueError("not_found mention must not contain proposed areas")
        if self.location_status != "not_found" and not self.location_evidence:
            raise ValueError("located/candidate mention requires real source areas")
        for source in self.location_evidence:
            if (
                source.page_no is None
                or source.normalized_bbox is None
                or source.normalized_bbox == (0, 0, 1, 1)
            ):
                raise ValueError(
                    "mention location requires a page and a local whole-page-normalized box"
                )
        if self.target_text is not None and self.target_text not in self.quote:
            raise ValueError("mention target must preserve its exact description quote")
        if self.end <= self.start:
            raise ValueError("mention end must follow start")
        if self.role != "unresolved" and not (self.reason or "").strip():
            raise ValueError("mention resolution requires a reason")
        return self

