physicalGeometry.excerpt:
"""Keep explicit non-part sizes out of calculations while retaining the source passport."""

from .envelope import envelope_geometry
from .models import AxialLengthChainRelation, DrawingPassport


def non_surface_dimension_refs(passport: DrawingPassport) -> set[str]:
    non_surface = {
        ref
        for f in passport.features
        if f.geometry_role in {"stock", "position"}
        for ref in f.dimension_refs
    }
    surface = {
        ref for f in passport.features if f.geometry_role == "surface" for ref in f.dimension_refs
    }
    stock = {
        ref for f in passport.features if f.geometry_role == "stock" for ref in f.dimension_refs
    }
    axial_refs = {
        ref
        for relation in passport.geometry_relations
        if isinstance(relation, AxialLengthChainRelation)
        for ref in relation.dimension_refs
    }
    # Keep explicit axial dependencies even when their owner is a position span.
    # The axial assessor still checks topology evidence, reference scope and bounds;
    # this does not promote stock sizes or unrelated offsets to finished geometry.
    axial_lengths = {
        d.id
        for d in passport.dimensions
        if d.id in axial_refs
        and d.id not in stock
        and d.kind in {"linear", "thickness"}
        and d.unit == "mm"
    }
    return non_surface - surface - axial_lengths


def physical_geometry(passport: DrawingPassport) -> DrawingPassport:
    passport = envelope_geometry(passport)
    excluded = non_surface_dimension_refs(passport)
    if not excluded:
        return passport
    return passport.model_copy(
        update={
            "dimensions": [d for d in passport.dimensions if d.id not in excluded],
            "geometry_relations": [
                r
                for r in passport.geometry_relations
                if not excluded.intersection(r.dimension_refs)

