function evidence(raw: string, verified = false, source?: Evidence): Evidence {
  return {
    ...(source ?? passport.part_name.evidence), raw_text: raw, confidence: null,
    recognition_status: verified ? 'observed' : 'uncertain',
    verification_status: verified ? 'operator_confirmed' : 'operator_corrected',
    // A manual addition does not inherit an unrelated source bounding box.
    normalized_bbox: source?.normalized_bbox ?? null, annotation_refs: source?.annotation_refs ?? [],
  };
}

async function persist(next: Passport, reason: string) {
  if (!reason.trim()) throw new Error('Укажите основание решения');
  next.revision = passport.revision + 1;
  const operator = getOperatorProfile();
  const result = await mutation.mutateAsync({ runId, payload: {
    passport: next, operator: operator.id || operator.name || 'operator', reason: reason.trim(),
  } });
  setDraft(null); setResolution(null); setLocationDraft(null);
  onRevisionApplied?.(result?.run_id);
}

async function saveSurface() {
  if (!draft) return;
  setError(''); setSaveFailure(null);
  try {
    if (!draft.name.trim()) throw new Error('Укажите название поверхности');
    if (!draft.reason.trim()) throw new Error('Укажите основание решения');
    const next = structuredClone(passport);
    next.features ??= []; next.dimensions ??= []; next.technical_requirements ??= [];
    const previous = features.find(item => item.id === draft.id);
    const mention = mentions.find(item => item.id === draft.mentionId);
    const locatedSource = draft.verified && mention?.location_status === 'located' && mention.location_evidence?.length === 1 ? mention.location_evidence[0] : undefined;
    const source = locatedSource ?? mention?.evidence ?? previous?.evidence;
    const ownRefs = [...(previous?.dimension_refs ?? [])];
    const contextRefs = [...(previous?.context_dimension_refs ?? [])];
    const addedDimensions: string[] = [];
    const requirementRefs = [...draft.requirements];
    for (const field of draft.fields) {
      if (!field.raw.trim()) throw new Error('Заполните надпись добавленного поля');
      if (field.kind === 'requirement') {
        next.technical_requirements.push({ id: field.id, raw_text: field.raw.trim(), category: 'other', evidence: evidence(field.raw, draft.verified, source) });
        requirementRefs.push(field.id);
      } else {
        const value = field.nominal.trim() ? Number(field.nominal.replace(',', '.')) : null;
        if (value !== null && (!Number.isFinite(value) || value < 0)) throw new Error('Номинал должен быть неотрицательным числом или оставаться пустым');
        next.dimensions.push({ id: field.id, kind: field.kind, role: 'other', raw_text: field.raw.trim(), nominal_value: value === null ? null : String(value),
          unit: field.kind === 'angle' ? 'deg' : 'mm', tolerance_type: 'none', count: 1, target_description: draft.name.trim(), view_description: draft.view.trim(),
          evidence: evidence(field.raw, draft.verified, source) } as Dimension);
        addedDimensions.push(field.raw.trim());
      }
    }
    const item: Feature = {
      ...(previous ?? { id: draft.id, raw_text: draft.name.trim(), count: 1, evidence: evidence(draft.name, draft.verified, source) }),
      kind: draft.kind, description: draft.name.trim(), physical_side: draft.side, geometry_role: draft.role,
      classification_evidence: evidence(draft.reason, draft.verified, source),
      dimension_refs: ownRefs, context_dimension_refs: contextRefs, requirement_refs: requirementRefs,
      ...(draft.dimensions !== (previous?.dimension_description ?? '') || addedDimensions.length ? { dimension_description: [draft.dimensions.trim(), ...addedDimensions].filter(Boolean).join('; ') } : {}),
      ...(draft.context !== (previous?.context_dimension_description ?? '') ? { context_dimension_description: draft.context.trim() } : {}),
      ...(draft.view !== (previous?.view_description ?? '') ? { view_description: draft.view.trim() } : {}),
      typed_parameters: draft.kind === 'thread' && (!previous || draft.side !== side(previous) || previous.kind !== draft.kind) ? { ...(previous?.typed_parameters?.kind === 'thread' ? previous.typed_parameters : {}), kind: 'thread', internal_external: draft.side === 'unknown' ? null : draft.side }
        : previous?.kind === draft.kind ? previous.typed_parameters : null,
    };
    const index = next.features.findIndex(f => f.id === item.id);
    if (index >= 0) next.features[index] = item; else next.features.push(item);
    if (mention) {
      if (draft.role !== 'surface') throw new Error('Из предупреждения добавляется поверхность; другую роль сохраните через «Связать / другая роль»');
      next.geometry_mentions = mentions.map(m => m.id === mention.id ? { ...m, role: 'surface', target_description: item.description || item.raw_text, view_description: draft.view.trim(), reason: draft.reason.trim(), evidence: evidence(m.quote, false, m.evidence) } : m);
    }
    await persist(next, draft.reason);
  } catch (caught) {
    if (caught instanceof OperatorRevisionSaveError) setSaveFailure(caught);
    else setError(caught instanceof Error ? caught.message : String(caught));
  }

