class ArtifactStore:
    def __init__(self, root: Path, repository: TraceRepository) -> None:
        self.root = root.resolve()
        self.repository = repository
        self.root.mkdir(parents=True, exist_ok=True)
        self._staging: ContextVar[list | None] = ContextVar("correction_staging", default=None)
        self.staging_diagnostics: list[str] = []
        self.recover_staging()

    @contextmanager
    def correction_staging(self):
        """OS leases keep restart recovery away from live concurrent writers."""
        leases: list = []
        token = self._staging.set(leases)
        try:
            yield
        finally:
            self._staging.reset(token)
            for artifact, ledger, lease in leases:
                try:
                    self.repository.get_artifact(artifact.id)
                except NoResultFound:
                    pass
                else:
                    ledger.unlink(missing_ok=True)
                finally:
                    lease.close()

    def recover_staging(self) -> None:
        journal = self.root / ".correction-staging"
        if not journal.exists():
            return
        for ledger in journal.glob("*.json"):
            with ledger.with_suffix(".lock").open("a+b") as lease:
                try:
                    _lock(lease)
                except OSError:
                    continue
                if not ledger.exists():
                    continue
                try:
                    artifact = Artifact.model_validate_json(ledger.read_bytes())
                except ValueError as error:
                    quarantine = self.root / ".correction-quarantine"
                    quarantine.mkdir(exist_ok=True)
                    os.replace(ledger, quarantine / ledger.name)
                    self.staging_diagnostics.append(
                        f"Invalid staging journal {ledger.name}: {error}"

