    """MVP stock screening from drawing geometry and the pinned NSI assortment."""
    return resolve_preview_read_model(run_id, request)[2]


def _read_dependencies(request, resolved) -> dict:
    catalog = getattr(request.app.state, "reference_catalog", None)
    registry = _assortment_registry(catalog, getattr(request.app.state, "editable_nsi", None))
    return {
        "implementation": implementation_hash(),
        "passport": resolved.passport.model_dump(mode="json"),
        "recognition_revision": resolved.token,
        "state": resolved.state.model_dump(mode="json") if resolved.state else None,
        "registry": [item.model_dump(mode="json") for item in registry],
        "candidates": [
            item.model_dump(mode="json")
            for item in (
                _drawing_reference_candidates(catalog, resolved.passport) if catalog else ()
            )
        ],
    }


def _read_key(artifact, dependencies: dict) -> str:
    return NSISnapshot.compute_hash(
        {"artifact_sha256": artifact.sha256, "metadata": artifact.metadata, **dependencies}
    )


def resolve_preview_read_model(
    run_id: str, request: Request
) -> tuple[DrawingPassport, NSISnapshot | StockBasisView, NormativeBlankPreview]:
    try:
        return _resolve_preview_read_model(run_id, request)
    except ValueError as error:
        raise HTTPException(status_code=422, detail=str(error)) from error


def _resolve_preview_read_model(
    run_id: str, request: Request
) -> tuple[DrawingPassport, NSISnapshot | StockBasisView, NormativeBlankPreview]:
    """Reuse a verified projection after restart, retaining full-source integrity."""
    runtime = get_runtime(request)
    try:
        passport = _latest_passport(runtime, run_id)
    except NoResultFound as error:
        raise _not_found("run", run_id) from error
    resolved = resolve_passport(runtime, run_id, mode="current")
    if resolved.passport != passport:
        raise HTTPException(status_code=409, detail="passport changed while reading stock inputs")
    dependencies = _read_dependencies(request, resolved)
    artifacts = _snapshot_artifacts(runtime, run_id)
    # Old artifacts without identity metadata take the full validation path.
    source = next(
        (
            item
            for item in artifacts
            if item.metadata.get("passport_id") == passport.passport_id
            and item.metadata.get("passport_revision") == passport.revision
        ),
        None,
    )
    if source is not None and source == artifacts[0] and source.metadata.get("formula_rules_ref"):
        key = _read_key(source, dependencies)
        for artifact in reversed(runtime.repository.list_artifacts(source.run_id)):
            if (
                artifact.kind != "stock_preview_read_model"
                or artifact.metadata.get("dependency_key") != key
            ):
                continue

