async def run(self, source, cycle):
    record = self.read(source, cycle)
    if stage(record).stage_key.startswith("operation:") or stage(record).stage_key in {
        "time",
        "estimate",
    }:
        from metall_mvp.workflows.d001_operations import run_operations

        await run_operations(self, source, cycle)
        return
    if record.execution_state != "queued" or not stage(record).attempt_no:
        return
    packet, owner = self.packet(record), job_id(record)
    started = monotonic()
    execution = None
    try:
        self.drafts.release_after_finish = False

        def allowed(db, job):
            current = project(self.store._read(db, source, cycle), CycleRecord)
            return current.execution_state in {"queued", "running"}

        self.drafts.publication_allowed = allowed
        pin = record.roles[0]
        if pin != role_pin(self.llm.provider.provider_id, pin.model, pin.requested_effort):
            raise CycleError("role_changed", "Pinned provider/instruction/contract differs")
        if self.drafts.upstream_stale_reasons(packet):
            raise CycleError("basis_changed", "Source changed in queue; no model called")
        self.drafts.reserve(source, "route", owner)
        try:
            completed = self.drafts.read(source, owner)
        except NoResultFound:
            completed = None
        if completed and completed.state == "completed":
            self.finish(source, cycle, completed, None)
            if len(record.roles) > 1:
                await self.run(source, cycle)
            return
        current = self.drafts.head(source)
        head = self.drafts.pin(
            packet,
            expected_revision=current.revision if current else 0,
            exclusive=True,
            reservation_owner=owner,
        )
        command = DraftRequest.model_validate(
            dict(
                request_id=owner,
                actor=record.actor,
                expected_revision=head.revision,
                model_id=pin.model,
                reasoning_effort=pin.requested_effort,
            )
        )
        execution, owned = self.drafts.claim(
            packet, command, provider_id=pin.provider, exclusive=True
        )
        if not owned:
            raise CycleError(
                "explicit_resume_required", "Saved execution is never dispatched twice"
            )
        original = self.drafts.before_dispatch

        def guard(job, inputs, attempt):
            original(job, inputs, attempt)
            self.before_dispatch(source, cycle, monotonic() - started)

        self.drafts.before_dispatch = guard
        self.drafts.max_format_attempts = 1
        try:
            execution = await execute_claimed_draft(
                self.drafts, packet, command, self.llm, execution
            )
        finally:
            self.drafts.before_dispatch = original
        self.finish(source, cycle, execution, monotonic() - started)
    except Exception as error:
        if execution:
            latest = self.drafts.read(source, execution.request_id)
            if latest.state in {"queued", "running"}:
                self.drafts.stop(latest, state="interrupted")
        self.finish(source, cycle, execution, monotonic() - started, error=str(error))
    finally:
        self.drafts.release(source, "route", owner)
    if len(record.roles) > 1:
        from metall_mvp.workflows.d001_operations import run_operations

        await run_operations(self, source, cycle)

