coordinatorBudget.excerpt:
def before_dispatch(self, source, cycle, elapsed=0):
    record = self.read(source, cycle)
    if record.execution_state not in {"queued", "running"}:
        raise DraftError("execution_stopped", "Cycle stopped before dispatch", 409)
    usage, limits = record.usage, record.limits
    if (
        usage.dispatches >= limits.max_dispatches
        or (
            limits.max_tokens is not None
            and (usage.tokens is None or usage.tokens >= limits.max_tokens)
        )
        or (
            limits.max_seconds is not None
            and (usage.seconds is None or usage.seconds + elapsed >= limits.max_seconds)
        )
    ):
        raise DraftError(
            "budget_exhausted", "Cycle budget exhausted or preceding usage UNKNOWN", 409
        )

    def apply(db, old):
        if old.execution_state not in {"queued", "running"}:
            raise CycleError("execution_stopped", "Cycle stopped before dispatch")
        return old.model_copy(
            update={
                "revision": old.revision + 1,
                "execution_state": "running",
                "usage": old.usage.model_copy(
                    update={
                        "dispatches": old.usage.dispatches + 1,
                        "tokens": None,
                        "seconds": None,
                        "unknown_reason": "Dispatch in flight; usage UNKNOWN until response",
                    }
                ),
                "stages": replace_stage(
                    old, execution_state="running", reason="Dispatch intent persisted"
                ),
            }
        )

    self.store.transition(self.command(record, "dispatch"), "dispatch", apply)

