def recover_cycles(runtime):
    """Startup only: no schema creation and no resubmission of model calls."""
    store = CycleStore(runtime.repository.engine)
    if s.cycles.name not in inspect(store.engine).get_table_names():
        return 0
    with store.engine.connect() as db:
        addresses = db.execute(select(s.cycles.c.source_run_id, s.cycles.c.cycle_id)).all()
    count = 0
    for source, cycle in addresses:
        envelope = store.read(source, cycle)
        if envelope.schema_version != "d001-cycle/1":
            continue
        try:
            old = project(envelope, CycleRecord)
        except CycleError:
            continue
        if (
            old.trigger != "explicit_d001_cycle"
            or old.execution_state not in {"queued", "running"}
            or not stage(old).attempt_no
        ):
            continue
        command = CycleCommand(
            source_run_id=source,
            cycle_id=cycle,
            request_id=f"{job_id(old)}:recover",
            action="update",
            expected_revision=old.revision,
            expected_basis_fingerprint=cycle_basis_fingerprint(old),
            actor="startup_recovery",
            reason="Interrupted; explicit resume required",
        )

        def apply(db, current):
            row = db.execute(
                select(requests.c.record).where(
                    requests.c.source_run_id == current.source_run_id,
                    requests.c.request_id == job_id(current),
                )
            ).scalar_one_or_none()

