def claim(
    self,
    packet: DraftPacket,
    request: DraftRequest,
    *,
    provider_id: str,
    exclusive: bool = False,
) -> tuple[DraftExecution, bool]:
    self.validate_input(packet)
    request = DraftRequest.model_validate_json(request.model_dump_json())
    if packet.role not in self.enabled_roles:
        raise DraftError(
            "direction_unavailable", "Direction is not enabled in this runtime", 409
        )
    try:
        previous = self.read(packet.basis.source_run_id, request.request_id)
    except NoResultFound:
        previous = None
    # A capability added later must not invalidate an exact saved replay.
    # Instruction/schema/model/request changes still participate in the digest.
    directions = (
        self.manifest(packet.basis.source_run_id, request.request_id)["available_directions"]
        if previous
        else {role: role in self.enabled_roles for role in ROLES if role != "time_estimation"}
    )
    instruction, instruction_hash = role_instruction(packet.role)
    schema = role_schema(packet.role)
    manifest: dict[str, Any] = {
        "actor": request.actor,
        "role": packet.role,
        "instruction_sha256": instruction_hash,
        "schema_sha256": fingerprint(schema),
        "provider_id": provider_id,
        "model_id": request.model_id,
        "reasoning_effort": request.reasoning_effort,
        "input_fingerprint": dependency_fingerprint(packet),
        "packet_sha256": fingerprint(packet.model_dump(mode="json")),
        "available_directions": directions,
        "content_check_version": CONTENT_CHECK_VERSION,
    }
    if isinstance(packet, BlankDraftPacket):
        origin = RouteDraft.model_validate(
            self.result(
                packet.basis.source_run_id, packet.origin_route_request_id
            ).published_payload
        )
        index = next(i for i, op in enumerate(origin.operations) if op == packet.basis.task)
        manifest["stage_context"] = {
            "operation_index": index,
            "is_initial_operation": index == 0,
            "predecessor_required": index > 0,
            "predecessor_result_provided": packet.basis.predecessor_result is not None,
        }
    elif isinstance(packet, CycleOperationPacket):
        manifest["stage_context"] = {
            "is_initial_operation": packet.predecessor_sha256 is None,
            "predecessor_required": packet.predecessor_sha256 is not None,
            "predecessor_result_provided": packet.basis.predecessor_result is not None,
        }
    # expected_revision participates in idempotency; a different retry is a new request.

