def publish_draft(
    runtime: TraceRuntime,
    packet: DraftPacket,
    raw: dict[str, Any] | None,
    *,
    is_initial_operation: bool | None = None,
) -> DraftResult:
    from metall_mvp.domain.d001_time import TimeDraft
    from metall_mvp.domain.route_drafts import CycleTimePacket

    if isinstance(packet, CycleTimePacket):
        from metall_mvp.workflows.d001_time import calculate

        try:
            value = TimeDraft.model_validate(raw)
            calculate(packet.basis, value, actor="time_estimation")
            return DraftResult(raw_payload=raw, published_payload=value.model_dump(mode="json"))
        except (ValueError, KeyError, IndexError, TypeError) as error:
            return DraftResult(
                raw_payload=raw,
                published_payload=None,
                diagnostics=(DraftDiagnostic(code="invalid_time", path="", message=str(error)),),
            )

    diagnostics = []

    def note(code: str, path: str, message: str) -> None:
        diagnostics.append(DraftDiagnostic(code=code, path=path, message=message))

    model = RouteDraft if isinstance(packet, RouteDraftPacket) else OperationDetailDraft
    try:
        parsed = model.model_validate(raw)
    except ValidationError as error:
        note("invalid_response", "", str(error))
        return DraftResult(raw_payload=raw, published_payload=None, diagnostics=tuple(diagnostics))
    if isinstance(packet, (BlankDraftPacket, CycleOperationPacket)) and isinstance(
        parsed, OperationDetailDraft
    ):
        if (
            parsed.operation_id != packet.basis.task.operation_id
            or parsed.result_state.state_id != packet.basis.expected_state.state_id
        ):
            note(
                "task_mismatch",
                "operation_id/result_state",
                "Response does not belong to the assigned task/state",
            )
            return DraftResult(
                raw_payload=raw,
                published_payload=None,
                diagnostics=tuple(diagnostics),
                explicit_gaps=packet.basis.known_gaps,
            )
        if parsed.equipment.machine_id != packet.basis.task.preliminary_equipment.machine_id:
            note(
                "equipment_changed",
                "equipment",
                "Equipment change must be a request, not a new assignment",
            )
            if parsed.outcome != "needs_route_review":
                return DraftResult(
                    raw_payload=raw,
                    published_payload=None,
                    diagnostics=tuple(diagnostics),
                    explicit_gaps=packet.basis.known_gaps,
                )
        if parsed.outcome == "described" and (
            packet.basis.known_gaps or not parsed.setup_and_tooling or not parsed.control_plan
        ):
            note(
                "described_unverified",
                "outcome",
                "Known gaps or missing sections prevent confirmed completeness",
            )
    content_issues = content_diagnostics(
        parsed,
        is_initial_operation=is_initial_operation,
        technical_ids=(packet.basis.input_state.state_id, packet.basis.task.operation_id)
        if isinstance(packet, (BlankDraftPacket, CycleOperationPacket))
        else (),

