def source_reference_errors(
    document: dict,
    payload: dict,
    source_id: str,
    *,
    additional_sources: dict[str, Any] | None = None,
) -> tuple[DraftDiagnostic, ...]:
    """Check addresses, without looking for substitute facts or altering raw."""
    errors = []

    def visit(node: Any, path: str = "") -> None:
        if isinstance(node, dict):
            for index, ref in enumerate(node.get("source_refs", [])):
                prefix, separator, pointer = ref.partition("#")
                candidate = (
                    prefix + "#/" + pointer
                    if separator and pointer and not pointer.startswith("/")
                    else ref
                )
                try:
                    resolve_source_ref(
                        document, candidate, source_id, additional_sources=additional_sources
                    )
                except (KeyError, IndexError, TypeError, ValueError):
                    errors.append(
                        DraftDiagnostic(
                            code="source_reference_missing",
                            path=path + "/source_refs/" + str(index),
                            message="Reference is outside the pinned source scope: " + ref,
                        )
                    )
            for key, child in node.items():
                visit(child, path + "/" + key)
        elif isinstance(node, list):
            for index, child in enumerate(node):
                visit(child, path + "/" + str(index))

    visit(payload)
    return tuple(errors)


