timeCalc.excerpt:
def calculate(basis, draft, *, actor, manual=False):
    """Enumerate exact work/control; full cells alone never imply coverage."""
    tasks = {task.operation_id: task for task in basis.route.operations}
    supplied = {op.operation_id: op for op in draft.operations}
    if not supplied.keys() <= tasks.keys():
        raise ValueError("Time operation is outside the exact map")
    entries = {entry["operation_id"]: entry for entry in basis.operations}
    all_recipes = {
        op.operation_id + "/" + c.component_id: c for op in draft.operations for c in op.components
    }
    if len(all_recipes) != sum(len(op.components) for op in draft.operations):
        raise ValueError("Duplicate component ID")
    document = basis.model_dump(mode="json")
    missing, operations = [], []
    for task in basis.route.operations:
        op_id = task.operation_id
        entry = entries.get(op_id)
        proposed = supplied.get(op_id)
        recipes = proposed.components if proposed else ()
        components, covered = [], set()
        required = set(basis.required_work[op_id])
        for recipe in recipes:
            if not set(recipe.covers) <= required or covered.intersection(recipe.covers):
                raise ValueError("Unknown or multiply charged work reference")
            covered.update(recipe.covers)
            if any(key.endswith("/setup") for key in recipe.covers) and recipe.scope != "batch":
                raise ValueError(
                    "Setup time belongs to the batch and is never multiplied by quantity"
                )
            if recipe.included_in:
                target = all_recipes.get(recipe.included_in)
                if (
                    target is None
                    or target.included_in
                    or target.method in {"unknown", "not_applicable"}
                    or target.scope != recipe.scope
                ):
                    raise ValueError(
                        "Shared work requires one applicable paying component in the same scope"
                    )
            elif recipe.method == "not_applicable" and any(
                "/control/" in key or "/work/" in key or "/requirement/" in key
                for key in recipe.covers
            ):
                raise ValueError(
                    "Required work cannot disappear as inapplicable; address shared work explicitly"
                )
            components.append(recipe_component(recipe, manual=manual, document=document))
        for scope in ("batch", "unit"):
            if not any(c.scope == scope for c in components):
                components.append(
                    TimeComponent(
                        component_id="unknown_" + scope,
                        title="Наладка" if scope == "batch" else "Штучная работа",
                        scope=scope,
                    )
                )
        gaps = sorted(required - covered)
        missing.extend(f"{key}: время работы не охвачено" for key in gaps)
        if not entry or entry["detail"]["outcome"] == "needs_route_review":
            missing.append(op_id + ": проработка отсутствует или требует пересмотра маршрута")
        operations.append(
            OperationTime(
                operation_id=op_id,
                title=task.title,
                machine_id=entry["detail"]["equipment"]["machine_id"]
                if entry
                else task.preliminary_equipment.machine_id,
                work_plan=tuple(entry["detail"]["work_plan"]) if entry else (),
                components=tuple(components),
                coverage_confirmed=not gaps and entry is not None,
                coverage_reason=proposed.coverage_reason
                if proposed
                else "Оценка времени не представлена",
                actor=actor,
                updated_at=datetime.now(UTC),
            )
        )
    summary = work_totals(tuple(operations), basis.quantity)
    missing.extend(summary.missing)
    missing.extend(
        item.requirement.text + ": требование без операции"
        for item in basis.route.unassigned_requirements
    )
    return tuple(operations), tuple(dict.fromkeys(missing))

