def costs(time, material, purchase, inputs):
    """Use the same money functions as legacy, without constructing a legacy RoutePlan."""
    missing = list(time.missing)
    conditions = list(inputs.assumptions)
    lines = []
    price, kg = number(inputs.material_rub_per_kg), number(purchase.paid_mass_kg)
    if kg is None:
        missing.append("Не установлен оплачиваемый закупочный расход и его политика")
    if price is None:
        missing.append("Не установлена цена материала")
    lines.append(
        D001CostLine(
            title="Материал",
            operation_id=None,
            rub_per_batch=format(material_cost(kg, price), "f")
            if kg is not None and price is not None
            else None,
            source=purchase.paid_mass_kg.source + "; " + inputs.material_rub_per_kg.source,
        )
    )
    rates = {r.operation_id: r.rub_per_hour for r in inputs.rates}
    if set(rates) - set(time.time_basis.operation_ids):
        raise CycleError("operation_mismatch", "Ставка относится к отсутствующей операции")
    for operation in time.operations:
        rate = rates.get(operation.operation_id)
        amount, complete = operation_cost(
            operation, time.time_basis.quantity.value, number(rate) if rate else None
        )
        if not complete:
            missing.append(operation.operation_id + ": время или охват работ не установлены")
        if rate is None or rate.value is None:
            missing.append(operation.operation_id + ": ставка не установлена")
        lines.append(
            D001CostLine(
                title=operation.title,
                operation_id=operation.operation_id,
                rub_per_batch=format(amount, "f") if amount is not None else None,
                source=rate.source if rate else "Ставка не задана",
            )
        )
    if not inputs.other_costs_reason:
        missing.append("Не определён состав дополнительных статей и правило их включения")
    for item in inputs.other_costs:
        if item.applicability != "required":
            conditions.append(item.title + ": " + item.reason)
            continue
        amount = number(item.rub_per_batch)
        if amount is None:
            missing.append(item.title + ": стоимость не установлена")
        lines.append(
            D001CostLine(
                title=item.title,
                operation_id=None,
                rub_per_batch=format(money(amount), "f") if amount is not None else None,
                source=item.rub_per_batch.source,
            )
        )
    if time.status != "sufficient":
        missing.append("Время маршрута определено частично")
    q = time.time_basis.quantity.value
    if q is None:
        missing.append("Количество деталей не установлено")
    if material.cut_norm_comment:
        conditions.append(material.cut_norm_comment)
    if time.evidence:
        conditions.extend(time.evidence.draft.assumptions)
    all_values = [
        inputs.material_rub_per_kg,
        *(r.rub_per_hour for r in inputs.rates),
        *(c.rub_per_batch for c in inputs.other_costs),
        *purchase.operands.values(),
        purchase.end_loss,
    ]
    conditions.extend(
        f"{v.basis}: {v.source}; {v.rationale}"
        for v in all_values
        if v.basis in {"mock", "estimate"}
    )
    conditions.append(
        "Численная достаточность не означает подтверждение цеховых норм или производственную приёмку"
    )
    accounted = sum(
        (Decimal(line.rub_per_batch) for line in lines if line.rub_per_batch is not None),
        Decimal(0),
    )
    total = accounted if not missing and q is not None else None
    return dict(
        lines=tuple(lines),
        missing=tuple(dict.fromkeys(missing)),
        conditions=tuple(dict.fromkeys(conditions)),
        status="partial" if missing else "sufficient",
        accounted_rub_per_batch=format(accounted, "f"),
        total_rub_per_batch=format(total, "f") if total is not None else None,
        total_rub_per_unit=format(money(total / q), "f") if total is not None and q else None,
    )

