class RouteDraft(PlanningModel):
    schema_version: Literal["d001-route-draft/1"]
    outcome: Literal["proposed", "needs_scope_review"]
    structure: Literal["linear"]
    states: tuple[DraftState, ...]
    operations: tuple[DraftOperationTask, ...]
    conditions: tuple[DraftIssue, ...] = ()
    unassigned_requirements: tuple[UnassignedDraftRequirement, ...] = ()
    source_observations: tuple[DraftIssue, ...] = ()

    @model_validator(mode="after")
    def linear_chain(self) -> Self:
        if self.outcome == "needs_scope_review":
            if self.states or self.operations or not self.conditions:
                raise ValueError("scope review requires no chain and a concrete condition")
            return self
        if not self.operations or len(self.states) != len(self.operations) + 1:
            raise ValueError("linear chain requires n operations and n+1 states")
        for name, values in (
            ("state", [s.state_id for s in self.states]),
            ("operation", [op.operation_id for op in self.operations]),
        ):
            if len(values) != len(set(values)):
                raise ValueError(f"duplicate {name} IDs")
        for index, op in enumerate(self.operations):
            if (op.input_state_id, op.output_state_id) != (
                self.states[index].state_id,
                self.states[index + 1].state_id,
            ):
                raise ValueError(f"{op.operation_id}: broken linear transition")
        return self


