timeDraft.excerpt:
class TimeRecipe(PlanningModel):
    component_id: Text
    title: Text
    scope: Literal["batch", "unit"]
    method: Literal["direct", "length_feed", "volume_rate", "unknown", "not_applicable"]
    operands: tuple[TimeOperand, ...]
    covers: tuple[Text, ...]
    # Shared work has one paying component; all other occurrences point to it.
    included_in: Text | None
    rationale: Text

    @model_validator(mode="after")
    def shape(self):
        if len({o.name for o in self.operands}) != len(self.operands):
            raise ValueError("Duplicate time operand")
        if len(set(self.covers)) != len(self.covers):
            raise ValueError("Duplicate work coverage")
        if self.included_in and (self.operands or self.method != "not_applicable"):
            raise ValueError("Shared work cannot be charged again")
        return self


class OperationTimeDraft(PlanningModel):
    operation_id: Text
    components: tuple[TimeRecipe, ...] = Field(min_length=1)
    coverage_reason: Text


class TimeDraft(PlanningModel):
    schema_version: Literal["d001-time-draft/1"] = "d001-time-draft/1"
    operations: tuple[OperationTimeDraft, ...]
    assumptions: tuple[Text, ...]

    @model_validator(mode="after")
    def unique_operations(self):
        if len({o.operation_id for o in self.operations}) != len(self.operations):
            raise ValueError("Duplicate operation time")
        return self


