export function D001CyclePanel({ source, enabled }: { source: string; enabled: boolean }) {
  const [params, setParams] = useSearchParams();
  const selected = params.get('cycle');
  const event = params.get('cycleEvent');
  const index = useCycleIndex(source, enabled);
  const workspace = useCycleWorkspace(source, selected, event);
  const history = useCycleHistory(source, selected);
  const command = useCycleCommand(source);
  const [showCreate, setShowCreate] = useState(false);
  const [reason, setReason] = useState('');
  const choose = (id: string) => { command.reset(); setParams(previous => { const next = new URLSearchParams(previous); next.set('tab', 'cycle'); if (id) next.set('cycle', id); else next.delete('cycle'); next.delete('cycleEvent'); return next; }); };
  const data = workspace.data;
  const record = data?.record;
  const control = (action: string) => { if (!record) return; void command.mutateAsync({ path: `/${record.cycle_id}/${action}`, body: { reason }, cycle: record, fingerprint: data?.basis_fingerprint }).catch(() => {}); };
  const save = (path: string, body: Record<string, unknown>) => command.mutateAsync({ path: `/${record!.cycle_id}${path}`, method: 'PUT', body, cycle: record!, fingerprint: data?.basis_fingerprint });
  const pending = Object.keys(sessionStorage).filter(k => k.startsWith(`metall.d001.pending:${source}:`)).map(key => { try { return { key, path: key.slice(`metall.d001.pending:${source}:`.length), value: JSON.parse(sessionStorage.getItem(key)!) as { intent: string; body: Record<string, unknown> } }; } catch { return null; } }).filter(v => v !== null);
  return <section className="space-y-4 p-4 text-sm" aria-label="Цикл до сметы">
    <div className="flex flex-wrap justify-between gap-3"><div><h2 className="text-lg font-semibold">Цикл до сметы</h2><p className="mt-1 text-muted">Чтение → карта → операции → время → смета. Каждый цикл сохраняет собственные результаты.</p></div><Button size="sm" variant="outline" onClick={() => setShowCreate(v => !v)}>{showCreate ? 'Скрыть новый цикл' : 'Подготовить новый цикл'}</Button></div>
    {!enabled && <p role="status">Дождитесь завершения чтения чертежа.</p>}
    {index.error && <p role="alert">Циклы недоступны: {index.error.message}</p>}
    <Select label="Сохранённый цикл" value={selected ?? ''} disabled={command.isPending} onChange={e => choose(e.target.value)} options={[{ value: '', label: 'Выберите цикл для просмотра' }, ...(index.data ?? []).map(item => ({ value: item.record?.cycle_id ?? String(item.envelope.saved.payload.cycle_id), label: item.record ? `${formatDateTime(item.record.created_at)} · ${executions[item.record.execution_state]} · ${item.record.cycle_id.slice(0, 8)}` : 'Неизвестная версия · только сохранённые данные' })), ...(selected && !index.data?.some(i => i.record?.cycle_id === selected) ? [{ value: selected, label: 'Цикл из ссылки' }] : [])]} />
    {!selected && !index.isLoading && !index.data?.length && <p>Сохранённых циклов пока нет. Подготовьте новый цикл по текущим входам.</p>}
    {!command.isPending && pending.map(p => <div key={p.key} className="rounded border border-warning/40 bg-warning-soft p-3 space-y-2"><p>Ответ на действие не подтверждён. Повтор использует тот же запрос и не создаёт вторую задачу.</p><Button size="sm" onClick={() => void command.mutateAsync({ path: p.path, method: /\/(time|estimate|operations\/[^/]+)$/.test(p.path) ? 'PUT' : 'POST', body: JSON.parse(p.value.intent) as Record<string, unknown> }).then(r => choose(r.receipt.cycle_id)).catch(() => {})}>Повторить неподтверждённый запрос</Button></div>)}
    {command.error && <p role="alert" className="text-danger whitespace-pre-wrap">{command.error.message}</p>}
    {showCreate && <CreateCycle source={source} enabled={enabled} command={command} choose={id => { choose(id); setShowCreate(false); }} />}
    {workspace.error && <p role="alert" className="text-danger">Сохранённый цикл недоступен: {workspace.error.message}</p>}
    {workspace.isLoading && <p role="status">Читаем точные результаты цикла…</p>}
    {selected && <Card><CardHeader><CardTitle>История выбранного цикла</CardTitle></CardHeader><CardContent className="space-y-3">
      {history.error && <p role="alert">История недоступна: {history.error.message}</p>}
      <Select label="Ревизия истории цикла" value={event ?? ''} disabled={command.isPending} onChange={e => setParams(previous => { const next = new URLSearchParams(previous); if (e.target.value) next.set('cycleEvent', e.target.value); else next.delete('cycleEvent'); return next; })} options={[{ value: '', label: 'Текущее состояние цикла' }, ...(history.data ?? []).map(e => ({ value: String(e.event_revision), label: `Запись ${e.event_revision} · ${e.command.actor} · ${e.command.reason}` }))]} />
      <Button size="sm" variant="outline" onClick={() => { void workspace.refetch(); void history.refetch(); void index.refetch(); }} disabled={command.isPending}>Обновить цикл</Button>
    </CardContent></Card>}
    {data && !record && <><p className="text-warning">Версия цикла не поддерживается. Сохранённые данные доступны для просмотра.</p><Sources value={data.envelope} /></>}
    {data && record && <>
      <Card><CardHeader><CardTitle>{executions[record.execution_state]} · {results[record.result_status]}</CardTitle></CardHeader><CardContent className="space-y-3">
        <p className="text-xs text-muted break-all">Цикл {record.cycle_id} · ревизия {record.revision} · {record.actor}</p>
        {data.historical && <p className="text-warning">Открыта сохранённая запись истории. Для правок вернитесь к текущему состоянию.</p>}
        <Messages items={data.stale_reasons} /><Messages items={record.stale_reasons} />
        <Progress record={record} />
        <ul className="space-y-1">{record.stages?.map(s => <li key={s.stage_key}>{stageName(s.stage_key)}: {executions[s.execution_state]} · {results[s.result_status]}<p className="text-xs text-muted">{stageReason(s)}</p></li>)}</ul>
        <details><summary className="cursor-pointer text-accent">Разрешённые роли и бюджет</summary><ul className="mt-2 space-y-1">{record.roles?.map(pin => <li key={pin.role}>{roles[pin.role] ?? pin.role}: {pin.provider} · {pin.model} · {pin.requested_effort}</li>)}</ul><p className="mt-2">Вызовы: {record.usage?.dispatches ?? 'не определено'} / {record.limits.max_dispatches}. Токены: {valueText(record.usage?.tokens)} / {record.limits.max_tokens ?? 'без лимита'}. Секунды: {valueText(record.usage?.seconds)} / {record.limits.max_seconds ?? 'без лимита'}.</p>{record.usage?.unknown_reason && <p>Расход известен не полностью: {record.usage.unknown_reason}</p>}</details>
        {!data.historical && <><Input label="Причина действия с циклом" value={reason} onChange={e => setReason(e.target.value)} /><div className="flex flex-wrap gap-2">
          {record.execution_state === 'queued' && <Button size="sm" disabled={command.isPending || !reason.trim() || !!data.stale_reasons?.length} onClick={() => control('start')}>Запустить цикл</Button>}
          {['waiting_decision', 'interrupted', 'failed', 'cancelled'].includes(record.execution_state) && (!data.route || !!data.packet?.basis.selected_blank) && <Button size="sm" disabled={command.isPending || !reason.trim() || !!data.stale_reasons?.length} onClick={() => control('resume')}>Продолжить цикл</Button>}
          {['running', 'queued', 'waiting_decision'].includes(record.execution_state) && <Button size="sm" variant="outline" disabled={command.isPending || !reason.trim()} onClick={() => control('cancel')}>Остановить цикл</Button>}
        </div><p className="text-xs text-muted">Продолжение разрешает оставшиеся закреплённые роли в прежнем бюджете. Сохранение правок само по себе модели не запускает.</p></>}
        <Sources value={data.envelope} />
      </CardContent></Card>
      <ResultView data={data} busy={command.isPending} save={save} />
    </>}
  </section>;
}

