def default_quantity(passport: DrawingPassport) -> PlanningQuantity:
    """Prefill the editable batch from the drawing, otherwise visibly assume one part."""
    drawing = passport.drawing_quantity
    if (
        drawing.value is not None
        and drawing.value >= 1
        and drawing.evidence.recognition_status == "observed"
    ):
        return PlanningQuantity(
            value=drawing.value, source="drawing", evidence="Количество деталей на чертеже"
        )
    return PlanningQuantity(
        value=1, source="default", evidence="На чертеже количество не указано: 1 шт. по умолчанию"

