def verify_native_checks(
    inputs: PlanningInput, states: tuple[RouteState, ...], evidence: dict | None
) -> CheckedStates:
    """Publish only executed numbers; a missing proof drops masses, never the route.

    Proof is a successful run of checks.py whose stdout carries the SHA-256 of
    the collected checks.json. Masses then come from that file, matched by
    state_id; the agent's prose and planning dimensions stay.
    """
    reason = None
    report = None
    files = (evidence or {}).get("files", {})
    if not evidence:
        reason = "запись исполнения проверочного кода отсутствует"
    elif evidence.get("input_errors"):
        reason = "входы или библиотека изменены во время проверки"
    elif evidence.get("output_errors"):
        reason = "проверочные файлы не сохранены или недоступны"
    elif evidence.get("execution_errors"):
        reason = "изолированное исполнение проверочного кода не подтверждено"
    elif not files.get("checks.py") or not files.get("checks.json"):
        reason = "checks.py/checks.json не сохранены"
    else:
        try:
            report = RouteCodeReport.model_validate_json(files["checks.json"])
        except ValidationError as error:
            reason = f"checks.json не соответствует схеме ({error.error_count()} ошибок)"
    if report is not None:
        result_hash = hashlib.sha256(files["checks.json"].encode()).hexdigest()
        source_hash = hashlib.sha256(files["checks.py"].encode()).hexdigest()
        executed = any(
            type(command.get("exit_code")) is int
            and command.get("exit_code") == 0
            and CHECK_MARKER + result_hash in command.get("stdout", "").splitlines()
            and SOURCE_MARKER + source_hash in command.get("stdout", "").splitlines()
            and command.get("source_sha256", source_hash) == source_hash
            for command in evidence.get("commands", [])  # type: ignore[union-attr]
        )
        if not executed:
            reason = "успешный запуск checks.py с хешем итогового checks.json не найден"
    if report is None or reason:
        return CheckedStates(
            states=_without_mass(states),
            verified=False,
            conditions=(f"Массы состояний не опубликованы: {reason}.",),
        )
    conditions = []
    code_states = {s.state_id: s for s in report.states}
    merged = []
    for state in states:
        code = code_states.get(state.state_id)
        if code is None:
            if state.mass_kg is not None:
                conditions.append(
                    f"Масса состояния {state.state_id} не опубликована: его нет в checks.json."
                )
            merged.append(state.model_copy(update={"mass_kg": None}))
            continue
        merged.append(
            state.model_copy(
                update={
                    "dimensions": code.dimensions,
                    "mass_kg": code.mass_kg,
                    "basis": code.basis,
                }
            )
        )
    if inputs.material_basis is None and any(s.mass_kg is not None for s in merged):
        conditions.append("Массы сняты: плотность материала не передана из НСИ.")
        merged = list(_without_mass(tuple(merged)))
    return CheckedStates(
        states=tuple(merged),
        checks=report.checks,
        verified=True,
        conditions=tuple(conditions),

